response:
**Gates before launch**

I run five gates before I launch the script. If any gate fails, I stop and tell you. First, I confirm that git status is clean. I also confirm that spe/predictions/r04.yaml and spe/plans/r04.md still match the commit from 10 minutes ago. I pass that commit hash to the script as args.predictionsCommit, and the preflight agent checks it again. Second, I run spe/evals/graders/grade.py on one output I made by hand that is correct and one that is wrong. The grader must score them 1 and 0. I also check that spe/evals/tasks/answers.json has all 50 ticket ids. Third, I check that config B has the 12-line prompt and 6 tools. I check that config C2 has the 12-line prompt, 3 tools, and the separate check_status tool. Fourth, I take the actual cost per trial from the round 3 run. I multiply it out to 500 trials, 50 judge calls, and the overhead for each agent call. I launch only if that total is under $40 with room to spare. The script also refuses to start when its own estimate goes over $40. Fifth, I save the script as spe/evals/harness/r04-workflow.js and make a local commit, so the run points to a committed script. I do not push.

Assumptions:
- I assumed that round 3 ran each trial through a runner command. The script takes that command as args.runnerCmd with {config}, {ticket}, {trial}, and {out} placeholders.
- I assumed that grade.py accepts a run directory and an answers path. You can override the command with args.gradeCmd.

Example args:

```json
{
  "predictionsCommit": "<hash of the r04 predictions/plan commit>",
  "ticketIds": ["<50 ids from answers.json>"],
  "runnerCmd": "<r03 runner> --config {config} --ticket {ticket} --trial {trial} --out {out}",
  "estTrialUsd": 0.04,
  "estJudgePerTicketUsd": 0.12,
  "estAgentOverheadUsd": 0.01,
  "batchTickets": 5
}
```

The numbers in the example are placeholders. The real values come from gate four.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4. Configs B and C2 on 50 tickets with 5 trials each. Code grader checks label.category and label.priority. Opus judge scores reply tone. Spend cap is $40.',
  phases: [
    { title: 'Preflight' },
    { title: 'Smoke' },
    { title: 'Trials' },
    { title: 'Code grade' },
    { title: 'Tone judge' },
    { title: 'Report' },
  ],
}

const CONFIGS = ['B', 'C2']
const TRIALS = 5
const N_TICKETS = 50
const CAP_USD = 40
const RUN_DIR = 'spe/evals/runs/r04'
const ANSWERS = 'spe/evals/tasks/answers.json'
const GRADER = 'spe/evals/graders/grade.py'
const JUDGE_RUBRIC = 'spe/evals/graders/judge.md'
const MODEL = 'opus'

const a = args ?? {}
const tickets = a.ticketIds ?? []
const runner = a.runnerCmd
const estTrialUsd = a.estTrialUsd
const estJudgeUsd = a.estJudgePerTicketUsd
const overhead = a.estAgentOverheadUsd ?? 0
const batchSize = a.batchTickets ?? 5
const gradeCmd = a.gradeCmd ?? `python ${GRADER} --runs ${RUN_DIR} --answers ${ANSWERS} --out ${RUN_DIR}/grades.json`

// Fail fast on bad args before any spend.
if (tickets.length !== N_TICKETS) throw new Error(`Expected ${N_TICKETS} ids in args.ticketIds, got ${tickets.length}`)
if (new Set(tickets).size !== N_TICKETS) throw new Error('args.ticketIds has duplicates')
if (!a.predictionsCommit) throw new Error('args.predictionsCommit is required')
if (!runner) throw new Error('args.runnerCmd is required')
if (typeof estTrialUsd !== 'number' || typeof estJudgeUsd !== 'number') {
  throw new Error('args.estTrialUsd and args.estJudgePerTicketUsd must be numbers')
}

const totalTrials = N_TICKETS * CONFIGS.length * TRIALS
const judgeReserve = (estJudgeUsd + overhead) * N_TICKETS
const plannedTotal = totalTrials * (estTrialUsd + overhead) + judgeReserve + 2 * overhead
if (plannedTotal > CAP_USD) {
  throw new Error(`Planned spend $${plannedTotal.toFixed(2)} is over the $${CAP_USD} cap`)
}
log(`Planned spend (estimate): $${plannedTotal.toFixed(2)} of $${CAP_USD}`)

let spent = 0

const PREFLIGHT_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    problems: { type: 'array', items: { type: 'string' } },
  },
  required: ['ok', 'problems'],
}

const TRIAL_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    reused: { type: 'boolean' },
    out_path: { type: 'string' },
    category: { type: ['string', 'null'] },
    priority: { type: ['string', 'null'] },
    reply: { type: ['string', 'null'] },
    cost_usd: { type: ['number', 'null'] },
    error: { type: ['string', 'null'] },
  },
  required: ['ok', 'reused', 'out_path', 'category', 'priority', 'reply', 'cost_usd', 'error'],
}

const GRADE_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    per_config: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          config: { type: 'string' },
          graded: { type: 'integer' },
          category_correct: { type: 'integer' },
          priority_correct: { type: 'integer' },
          both_correct: { type: 'integer' },
          missing: { type: 'integer' },
        },
        required: ['config', 'graded', 'category_correct', 'priority_correct', 'both_correct', 'missing'],
      },
    },
    error: { type: ['string', 'null'] },
  },
  required: ['ok', 'per_config', 'error'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          score: { type: 'number' },
          rationale: { type: 'string' },
        },
        required: ['id', 'score', 'rationale'],
      },
    },
  },
  required: ['scores'],
}

function outPath(u) {
  return `${RUN_DIR}/${u.config}/${u.ticket}/t${u.trial}.json`
}

function trialPrompt(u) {
  const out = outPath(u)
  const cmd = runner
    .replaceAll('{config}', u.config)
    .replaceAll('{ticket}', u.ticket)
    .replaceAll('{trial}', String(u.trial))
    .replaceAll('{out}', out)
  return `You run one trial of SPE round 4. Do not change the command, the config, or any file other than ${out}.
If ${out} already exists and parses as JSON with label and reply fields, do not rerun it. Read it, set reused to true, and set cost_usd to 0.
Otherwise run exactly this command from the repo root:
${cmd}
Then read ${out}. Return label.category, label.priority, and the reply text exactly as written.
Return the cost in USD that the runner printed. Return null if it printed no cost.
Do not open ${ANSWERS} or ${JUDGE_RUBRIC}.
If the command fails, set ok to false and put the last 20 lines of stderr in error.`
}

async function runTrial(u, phaseName) {
  const r = await agent(trialPrompt(u), {
    label: `${u.config}/${u.ticket}/t${u.trial}`,
    phase: phaseName,
    schema: TRIAL_SCHEMA,
    model: MODEL,
  })
  spent += overhead
  if (r && !r.reused) spent += typeof r.cost_usd === 'number' && r.cost_usd >= 0 ? r.cost_usd : estTrialUsd
  return { ...u, ...(r ?? { ok: false, error: 'agent returned nothing' }) }
}

function hash(s) {
  let h = 2166136261
  for (const c of s) {
    h ^= c.charCodeAt(0)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

// Deterministic shuffle so a resumed run gives the judge the same order.
function order(ticket, n) {
  return Array.from({ length: n }, (_, i) => i)
    .sort((x, y) => hash(`${ticket}:${x}`) - hash(`${ticket}:${y}`))
}

function judgePrompt(ticket, items) {
  return `You are the tone judge for SPE round 4. Read ${JUDGE_RUBRIC} and apply it exactly.
You may read the ticket text for ${ticket} under spe/evals/tasks/. Read no other files.
Below are ${items.length} candidate replies to ticket ${ticket}. Each reply has an anonymous id.
Score each reply against the rubric on its own. Do not try to guess which system wrote which reply.

${items.map(x => `--- ${x.id} ---\n${x.reply}`).join('\n\n')}

Return exactly one score entry for each id.`
}

// Preflight
phase('Preflight')
const pre = await agent(
  `Check the SPE round 4 preconditions in this repo. Make no edits. Report each failed check in problems.
1. "git cat-file -e ${a.predictionsCommit}:spe/predictions/r04.yaml" succeeds.
2. "git diff --quiet ${a.predictionsCommit} -- spe/predictions/r04.yaml spe/plans/r04.md" exits 0.
3. ${ANSWERS} parses as JSON and has label.category and label.priority for each of these ids: ${tickets.join(', ')}.
4. ${GRADER} and ${JUDGE_RUBRIC} exist.
5. The script named in this runner template exists: ${runner}
6. ${RUN_DIR} does not exist, or it holds only output from an earlier partial run of round 4.
Set ok to true only if every check passes.`,
  { label: 'preflight', phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: MODEL },
)
spent += overhead
if (!pre?.ok) throw new Error(`Preflight failed: ${(pre?.problems ?? ['no result']).join(' | ')}`)

// Smoke: one trial per config on the first ticket, then grade it.
phase('Smoke')
const smoke = await parallel(CONFIGS.map(config => () => runTrial({ ticket: tickets[0], config, trial: 1 }, 'Smoke')))
const smokeBad = smoke.filter(r => !r.ok || !r.category || !r.priority || !r.reply)
if (smokeBad.length) {
  throw new Error(`Smoke failed: ${smokeBad.map(r => `${r.config}: ${r.error ?? 'missing fields'}`).join(' | ')}`)
}
log(`Smoke passed. Spent $${spent.toFixed(2)} (estimate)`)

// Trials, in ticket batches, with a budget check before each batch.
phase('Trials')
const results = []
let truncated = false
for (let i = 0; i < tickets.length; i += batchSize) {
  const batch = tickets.slice(i, i + batchSize)
  const units = batch.flatMap(ticket =>
    CONFIGS.flatMap(config =>
      Array.from({ length: TRIALS }, (_, k) => ({ ticket, config, trial: k + 1 }))))
  const projected = spent + units.length * (estTrialUsd + overhead) + judgeReserve
  if (projected > CAP_USD) {
    truncated = true
    log(`Stopping before ticket ${i + 1}. Projected $${projected.toFixed(2)} is over the cap.`)
    break
  }
  const out = await parallel(units.map(u => () => runTrial(u, 'Trials')))
  results.push(...out)
  const failed = out.filter(r => !r.ok).length
  log(`Tickets ${i + 1}-${i + batch.length}: ${failed} of ${out.length} failed. Spent $${spent.toFixed(2)} (estimate)`)
  if (failed > out.length * 0.1) {
    truncated = true
    log('More than 10% of this batch failed. Stopping to protect the budget.')
    break
  }
}

// Code grade, run once over all outputs.
phase('Code grade')
const grade = await agent(
  `Run this command from the repo root and make no other changes:
${gradeCmd}
Read ${RUN_DIR}/grades.json. For each config (${CONFIGS.join(', ')}), return the number of trials graded,
the number with label.category correct, the number with label.priority correct, the number with both correct,
and the number of expected outputs that were missing. If the command fails, set ok to false and put the error in error.`,
  { label: 'grade', phase: 'Code grade', schema: GRADE_SCHEMA, model: MODEL },
)
spent += overhead

// Tone judge, one blinded call per ticket.
phase('Tone judge')
const byTicket = new Map()
for (const r of results) {
  if (!r.ok || !r.reply) continue
  if (!byTicket.has(r.ticket)) byTicket.set(r.ticket, [])
  byTicket.get(r.ticket).push(r)
}
let judged = []
const judgeCost = byTicket.size * (estJudgeUsd + overhead)
if (spent + judgeCost > CAP_USD) {
  truncated = true
  log(`Skipping tone judge. Spent $${spent.toFixed(2)} plus judge $${judgeCost.toFixed(2)} is over the cap.`)
} else {
  judged = await parallel(Array.from(byTicket.entries()).map(([ticket, rs]) => async () => {
    const blinded = order(ticket, rs.length).map((idx, j) => ({ id: `R${j + 1}`, reply: rs[idx].reply, src: rs[idx] }))
    const j = await agent(judgePrompt(ticket, blinded), {
      label: `judge/${ticket}`,
      phase: 'Tone judge',
      schema: JUDGE_SCHEMA,
      model: MODEL,
    })
    spent += estJudgeUsd + overhead
    const src = new Map(blinded.map(b => [b.id, b.src]))
    const got = (j?.scores ?? []).filter(s => src.has(s.id))
    if (got.length !== blinded.length || new Set(got.map(s => s.id)).size !== blinded.length) {
      return { ticket, ok: false, scores: [] }
    }
    return {
      ticket,
      ok: true,
      scores: got.map(s => ({ config: src.get(s.id).config, trial: src.get(s.id).trial, score: s.score, rationale: s.rationale })),
    }
  }))
}

// Report
phase('Report')
const summary = CONFIGS.map(config => {
  const rs = results.filter(r => r.config === config)
  const tone = judged.flatMap(j => j.scores).filter(s => s.config === config).map(s => s.score)
  return {
    config,
    trials_planned: N_TICKETS * TRIALS,
    trials_ok: rs.filter(r => r.ok).length,
    trials_failed: rs.filter(r => !r.ok).length,
    code_grade: (grade?.per_config ?? []).find(p => p.config === config) ?? null,
    tone_n: tone.length,
    tone_mean: tone.length ? tone.reduce((s, x) => s + x, 0) / tone.length : null,
  }
})

log(`Done. Spent $${spent.toFixed(2)} of $${CAP_USD} (estimate). Truncated: ${truncated}`)

return {
  round: 4,
  predictions_commit: a.predictionsCommit,
  cap_usd: CAP_USD,
  spent_usd_estimate: Number(spent.toFixed(2)),
  truncated,
  grade_ok: !!grade?.ok,
  grade_error: grade?.error ?? null,
  summary,
  trial_failures: results.filter(r => !r.ok).map(r => ({ config: r.config, ticket: r.ticket, trial: r.trial, error: r.error })),
  judge_failures: judged.filter(j => !j.ok).map(j => j.ticket),
  tone_scores: judged.flatMap(j => j.scores.map(s => ({ ticket: j.ticket, ...s }))),
}
```

The script does not touch the filesystem, so it only returns the results. Once it finishes, I write the returned object to spe/evals/results/r04.json and make a local commit for that step. Then I compare the results against spe/predictions/r04.yaml.
